<?php require '../includes/db.php';require '../includes/functions.php';admin_required();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$t=trim($_POST['title']??'');$a=trim($_POST['author']??'');$c=trim($_POST['category']??'');$p=(float)($_POST['price']??0);$st=max(0,(int)($_POST['stock']??0));$d=trim($_POST['description']??'');if($t&&$a&&$c&&$p>=0){$s=$conn->prepare('INSERT INTO books(title,author,category,price,stock,description) VALUES(?,?,?,?,?,?)');$s->bind_param('ss sdis',$t,$a,$c,$p,$st,$d);$s->execute();$msg='Book added.';}}$rows=$conn->query('SELECT * FROM books ORDER BY id DESC');$page_title='Admin Books';include '../includes/header.php';?><h1>Admin · Inventory</h1><?php if($msg):?><p class="notice"><?=e($msg)?></p><?php endif;?><div class="panel"><h2>Add Book</h2><form method="post"><label>Title</label><input name="title" required><label>Author</label><input name="author" required><label>Category</label><input name="category" required><label>Price</label><input name="price" type="number" min="0" step=".01" required><label>Stock</label><input name="stock" type="number" min="0" required><label>Description</label><textarea name="description"></textarea><button class="btn">Add</button></form></div><h2>Inventory List</h2><table><tr><th>Title</th><th>Price</th><th>Stock</th></tr><?php while($x=$rows->fetch_assoc()):?><tr><td><?=e($x['title'])?></td><td><?=cash($x['price'])?></td><td><?=$x['stock']?></td></tr><?php endwhile;?></table><?php include '../includes/footer.php';?>
